import fs from 'node:fs';
import path from 'node:path';
export function collect({ root, paths }) {
  return paths.flatMap((p) => (fs.readFileSync(path.join(root, p), 'utf8').match(/PLANT/g) ?? []).map(() => ({ rule: 'plant', path: p })));
}

