import fs from 'node:fs';
import path from 'node:path';
// Each file's size in bytes, keyed by its base name.
export function measure({ root, paths }) {
  return Object.fromEntries(paths.map((p) => [path.basename(p), fs.statSync(path.join(root, p)).size]));
}
